<?php
/**
 * Plugin Name: Wrrapd Icon Deploy Once
 * Description: Overwrite legacy ms-icon with centered focus-W.
 * Version: 1.1.1
 */
if ( ! defined( 'ABSPATH' ) ) { exit; }
add_action( 'rest_api_init', function () {
  register_rest_route( 'wrrapd/v1', '/icon-deploy', array(
    'methods' => 'POST',
    'permission_callback' => function ( $req ) {
      $token = (string) $req->get_header( 'x_wrrapd_mu_deploy_token' );
      if ( $token === '' ) { $token = (string) $req->get_param( 'token' ); }
      return hash_equals( 'wrrapd-sg-deploy-2026-09-18-k7m3', $token );
    },
    'callback' => 'wrrapd_icon_deploy_run',
  ) );
} );
function wrrapd_icon_deploy_run() {
  $bin = base64_decode( '' );
  $paths = array(
    trailingslashit( WP_CONTENT_DIR ) . 'uploads/2023/02/ms-icon-144x144-1.png',
    '/home/customer/www/apply.wrrapd.com/public_html/wp-content/uploads/2023/02/ms-icon-144x144-1.png',
    '/home/customer/www/apply.wrrapd.com/public_html/wrapstars/wp-content/uploads/2023/02/ms-icon-144x144-1.png',
  );
  // Also re-pull focus pack from local raw github main if available
  $files = array('favicon.ico','icon-16.png','icon-32.png','icon-48.png','icon-64.png','icon-96.png','icon-128.png','icon-180.png','icon-192.png','icon-256.png','icon-512.png','icon-1024.png','icon-2048.png','icon-focus-512.png');
  $base = 'https://raw.githubusercontent.com/phill86518/WrrapdExtension-main/main/wordpress/icons/favicon/';
  $dirs = array(
    trailingslashit( WP_CONTENT_DIR ) . 'mu-plugins/icons/favicon',
    '/home/customer/www/apply.wrrapd.com/public_html/wp-content/mu-plugins/icons/favicon',
    '/home/customer/www/apply.wrrapd.com/public_html/wrapstars/wp-content/mu-plugins/icons/favicon',
  );
  $out = array();
  foreach ( $paths as $path ) {
    if ( ! is_dir( dirname( $path ) ) ) { $out[] = array('path'=>$path,'ok'=>false,'error'=>'no dir'); continue; }
    $ok = file_put_contents( $path, $bin );
    $out[] = array('path'=>$path,'ok'=>$ok!==false,'bytes'=>strlen($bin),'kind'=>'ms-overwrite');
  }
  foreach ( $dirs as $dir ) {
    if ( ! is_dir( $dir ) ) { @wp_mkdir_p( $dir ); }
    if ( ! is_dir( $dir ) ) { $out[] = array('dir'=>$dir,'ok'=>false,'error'=>'missing'); continue; }
    foreach ( $files as $file ) {
      $resp = wp_remote_get( $base . $file, array( 'timeout' => 60 ) );
      if ( is_wp_error( $resp ) || (int) wp_remote_retrieve_response_code( $resp ) !== 200 ) {
        $out[] = array('dir'=>$dir,'file'=>$file,'ok'=>false); continue;
      }
      $body = (string) wp_remote_retrieve_body( $resp );
      $ok = file_put_contents( trailingslashit($dir).$file, $body );
      $out[] = array('dir'=>$dir,'file'=>$file,'ok'=>$ok!==false,'bytes'=>strlen($body));
    }
  }
  return new WP_REST_Response( array( 'ok' => true, 'results' => $out ), 200 );
}
